4\u0435\u043b\u044c \u043f\u0443\u0437\u044b\u0440\u044c\u043a\u043e\u0432, \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u043c\u0430\u044f \u043a\u0430\u043a \u0442\u0435\u043e\u0440\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441.\n\n## 1. \u0413\u0438\u043f\u043e\u0442\u0435\u0437\u0430 \u043a\u0430\u043a \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0438\u0440\u0443\u0435\u043c\u044b\u0439 \u0432\u043e\u043f\u0440\u043e\u0441\n\n- **H1 (\u043e\u0434\u043d\u043e-\u043f\u0440\u043e\u0445\u043e\u0434\u043d\u044b\u0435 \u043c\u0435\u0442\u043e\u0434\u044b):** \u0434\u043b\u044f 1F1B, 1F1B-I \u0438 ZB-1p \u0441\u0440\u0435\u0434\u043d\u0438\u0439 steady-state throughput (tokens/s) **\u0440\u0430\u0441\u0442\u0451\u0442** \u0441 \u0447\u0438\u0441\u043b\u043e\u043c \u043c\u0438\u043a\u0440\u043e\u0431\u0430\u0442\u0447\u0435\u0439 m \u0438 \u0432\u044b\u0445\u043e\u0434\u0438\u0442 \u043d\u0430 \u043f\u043b\u0430\u0442\u043e \u043f\u0440\u0438 m \u226b p.\n- **H2 (ZB-2p):** ZB-2p \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u0442 \u0432\u044b\u0441\u043e\u043a\u0443\u044e throughput **\u043f\u0440\u0438 \u043c\u0430\u043b\u044b\u0445 m \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0433\u043e \u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c\u0430** (\u043d\u0435 \u00ab\u0432\u044b\u0448\u0435 \u0432\u0441\u0435\u0445 \u043c\u0435\u0442\u043e\u0434\u043e\u0432 \u043f\u0440\u0438 \u0432\u0441\u0435\u0445 m\u00bb).\n- \u0424\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u0444\u0438\u043a\u0441\u0430\u0446\u0438\u0438 (a priori): \u043f\u0440\u0438 \u0441\u0430\u043c\u043e\u043c \u043c\u0430\u043b\u043e\u043c m \u0438\u0437 \u0434\u0438\u0430\u043f\u0430\u0437\u043e\u043d\u0430 \u043e\u0434\u043d\u043e-\u043f\u0440\u043e\u0445\u043e\u0434\u043d\u044b\u0435 \u043c\u0435\u0442\u043e\u0434\u044b \u0434\u043e\u0441\u0442\u0438\u0433\u0430\u044e\u0442 \u2264 85% \u0441\u0432\u043e\u0435\u0433\u043e \u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c\u0430, \u0430 ZB-2p \u2265 95% \u0441\u0432\u043e\u0435\u0433\u043e \u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c\u0430; \u043f\u0440\u0438 \u044d\u0442\u043e\u043c \u0443 \u0432\u0441\u0435\u0445 \u043c\u0435\u0442\u043e\u0434\u043e\u0432 \u043f\u0440\u0438 \u0431\u043e\u043b\u044c\u0448\u0438\u0445 m \u0440\u0430\u0437\u043b\u0438\u0447\u0438\u0435 \u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0441\u044f \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u043d\u0435\u0440\u0430\u0437\u043b\u0438\u0447\u0438\u043c\u044b\u043c \u0438\u043b\u0438 \u043c\u0430\u043b\u044b\u043c.\n\n## 2. \u041c\u0435\u0442\u0440\u0438\u043a\u0430 \u0438 \u0435\u0434\u0438\u043d\u0438\u0446\u044b\n\n- **\u041e\u0441\u043d\u043e\u0432\u043d\u0430\u044f \u043c\u0435\u0442\u0440\u0438\u043a\u0430:** throughput = \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u0437\u0430 \u043e\u0434\u0438\u043d \u0431\u0430\u0442\u0447 / \u0441\u0440\u0435\u0434\u043d\u0435\u0435 steady-state \u0432\u0440\u0435\u043c\u044f \u0431\u0430\u0442\u0447\u0430, \u0435\u0434\u0438\u043d\u0438\u0446\u044b **tokens/s** (\u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u043d\u043e\u0440\u043c\u0438\u0440\u0443\u0435\u043c \u043d\u0430 \u0447\u0438\u0441\u043b\u043e GPU \u2192 tokens/s/GPU, \u0447\u0442\u043e\u0431\u044b \u043d\u0438\u0432\u0435\u043b\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0440\u0430\u0437\u043d\u044b\u0439 \u0440\u0430\u0437\u043c\u0435\u0440 \u043c\u0438\u0440\u0430 \u043f\u0440\u0438 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0438 \u0441 \u043b\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u043e\u0439).\n- \u0418\u0437\u043c\u0435\u0440\u0435\u043d\u0438\u0435: \u043c\u043e\u043d\u043e\u0442\u043e\u043d\u043d\u044b\u0435 \u0447\u0430\u0441\u044b (\u0432\u0440\u0435\u043c\u044f \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u0430/\u0434\u0440\u0430\u0439\u0432\u0435\u0440\u0430) \u043d\u0430 \u0434\u0440\u0430\u0439\u0432\u0435\u0440\u0435; \u0432\u0440\u0435\u043c\u044f \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u043f\u043e **steady-state** \u0438\u0442\u0435\u0440\u0430\u0446\u0438\u044f\u043c; \u043f\u0435\u0440\u0432\u044b\u0435 N=5 \u0438\u0442\u0435\u0440\u0430\u0446\u0438\u0439 (warmup) \u043e\u0442\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u044e\u0442\u0441\u044f.\n- \u0427\u0438\u0441\u043b\u043e \u0438\u0437\u043c\u0435\u0440\u044f\u0435\u043c\u044b\u0445 \u0438\u0442\u0435\u0440\u0430\u0446\u0438\u0439 K \u043f\u043e\u0441\u043b\u0435 warmup \u2014 \u0430\u0434\u0430\u043f\u0442\u0438\u0432\u043d\u043e\u0435: \u043d\u0430\u0447\u0438\u043d\u0430\u0435\u043c \u0441 K=30; \u0435\u0441\u043b\u0438 \u043f\u043e\u0441\u043b\u0435 warmup \u043a\u043e\u044d\u0444\u0444\u0438\u0446\u0438\u0435\u043d\u0442 \u0432\u0430\u0440\u0438\u0430\u0446\u0438\u0438 (CV) \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u0438\u0442\u0435\u0440\u0430\u0446\u0438\u0438 > 5%, \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0432\u0430\u0435\u043c K \u0434\u043e \u2265 50 (\u0438 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c, \u0447\u0442\u043e CV \u043f\u0430\u0434\u0430\u0435\u0442 \u043d\u0438\u0436\u0435 \u043f\u043e\u0440\u043e\u0433\u0430).\n\n## 3. \u041a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044f \u043c\u043e\u0434\u0435\u043b\u0438 \u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043c\u0438\u0440\n\n- \u041c\u043e\u0434\u0435\u043b\u044c: \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0442\u0440\u0430\u043d\u0441\u0444\u043e\u0440\u043c\u0435\u0440\u043d\u0430\u044f LM GPT-\u043f\u043e\u0434\u043e\u0431\u043d\u043e\u0433\u043e \u0442\u0438\u043f\u0430, \u0440\u0430\u0437\u0431\u0438\u0432\u0430\u0435\u043c\u0430\u044f \u043d\u0430 p \u0441\u0442\u0430\u0434\u0438\u0439 \u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d\u0430; \u0446\u0435\u043b\u0435\u0432\u043e\u0439 \u043c\u0430\u0441\u0448\u0442\u0430\u0431 ~350M\u20131.3B \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432 (\u0442\u043e\u0447\u043d\u044b\u0435 hidden/heads/seq_len \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u043e\u0434\u0438\u043d \u0440\u0430\u0437 \u0438 \u043d\u0435\u0438\u0437\u043c\u0435\u043d\u043d\u044b \u0432\u043e \u0432\u0441\u0435\u0445 \u044f\u0447\u0435\u0439\u043a\u0430\u0445). \u042d\u0442\u043e **\u0432\u044b\u0431\u043e\u0440 \u0434\u0438\u0437\u0430\u0439\u043d\u0430**, \u0440\u0435\u0430\u043b\u0438\u0437\u0443\u0435\u043c\u044b\u0439 \u043f\u0440\u0438 \u043f\u043e\u044f\u0432\u043b\u0435\u043d\u0438\u0438 \u043a\u043e\u0434\u0430/\u0436\u0435\u043b\u0435\u0437\u0430.\n- **\u0424\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 p = 8** (\u0437\u0430\u043f\u0430\u0441\u043d\u043e\u0439 \u0432\u0430\u0440\u0438\u0430\u043d\u0442 p = 4), \u043d\u0435\u0438\u0437\u043c\u0435\u043d\u043d\u044b\u0439 \u0432\u043e \u0432\u0441\u0435\u0445 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u0445; \u0433\u043b\u0443\u0431\u0438\u043d\u0430 \u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d\u0430 = p. \u041a\u0430\u0436\u0434\u0430\u044f \u0441\u0442\u0430\u0434\u0438\u044f \u0434\u043e\u043b\u0436\u043d\u0430 \u043f\u043e\u043c\u0435\u0449\u0430\u0442\u044c\u0441\u044f \u0432 \u043f\u0430\u043c\u044f\u0442\u044c \u043e\u0434\u043d\u043e\u0439 GPU \u043f\u0440\u0438 \u0441\u0430\u043c\u043e\u043c \u043c\u0430\u043b\u0435\u043d\u044c\u043a\u043e\u043c m (\u043d\u0430\u0438\u0431\u043e\u043b\u044c\u0448\u0435\u043c \u043c\u0438\u043a\u0440\u043e\u0431\u0430\u0442\u0447\u0435).\n- \u0421\u0443\u043c\u043c\u0430\u0440\u043d\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u0437\u0430 \u0438\u0442\u0435\u0440\u0430\u0446\u0438\u044e **\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043e \u0432\u043e \u0432\u0441\u0435\u0445 m**; \u043f\u0440\u0438 \u0440\u043e\u0441\u0442\u0435 m \u043f\u0440\u043e\u043f\u043e\u0440\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e \u0443\u043c\u0435\u043d\u044c\u0448\u0430\u0435\u0442\u0441\u044f \u0440\u0430\u0437\u043c\u0435\u0440 \u043c\u0438\u043a\u0440\u043e\u0431\u0430\u0442\u0447\u0430 (\u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u044b\u0439 \u0431\u0430\u0442\u0447 \u0432 \u0442\u043e\u043a\u0435\u043d\u0430\u0445 \u043f\u043e\u0441\u0442\u043e\u044f\u043d\u0435\u043d), \u0447\u0442\u043e\u0431\u044b \u0440\u043e\u0441\u0442 m \u043d\u0435 \u043e\u0437\u043d\u0430\u0447\u0430\u043b \u0440\u043e\u0441\u0442 \u043e\u0431\u044a\u0451\u043c\u0430 \u0440\u0430\u0431\u043e\u0442\u044b.\n\n## 4. \u0414\u0438\u0430\u043f\u0430\u0437\u043e\u043d \u0447\u0438\u0441\u043b\u0430 \u043c\u0438\u043a\u0440\u043e\u0431\u0430\u0442\u0447\u0435\u0439\n\n- m \u2208 {2, p/2, p, 2p, 4p, 8p, 16p} \u2192 \u043f\u0440\u0438 p=8: {2, 4, 8, 16, 32, 64, 128}.\n- \u041c\u0430\u043b\u044b\u0435 m (m < p+1): \u043e\u0431\u043b\u0430\u0441\u0442\u044c, \u0433\u0434\u0435 \u043f\u0443\u0437\u044b\u0440\u044c\u043a\u0438 \u0443 \u043e\u0434\u043d\u043e-\u043f\u0440\u043e\u0445\u043e\u0434\u043d\u044b\u0445 \u043c\u0435\u0442\u043e\u0434\u043e\u0432 \u043c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u044b \u0438 \u0440\u0430\u0437\u043b\u0438\u0447\u0438\u0435 \u043c\u0435\u0436\u0434\u0443 \u043c\u0435\u0442\u043e\u0434\u0430\u043c\u0438 \u043d\u0430\u0438\u0431\u043e\u043b\u044c\u0448\u0435\u0435.\n- \u0411\u043e\u043b\u044c\u0448\u0438\u0435 m (m \u226b p): \u043f\u0443\u0437\u044b\u0440\u044c\u043a\u0438 \u2192 0, \u043a\u0440\u0438\u0432\u044b\u0435 \u0432\u044b\u0445\u043e\u0434\u044f\u0442 \u043d\u0430 \u043f\u043b\u0430\u0442\u043e \u2014 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043d\u0430\u0441\u044b\u0449\u0435\u043d\u0438\u044f \u0438 \u043e\u0446\u0435\u043d\u043a\u0430 \u00ab\u0430\u0441\u0438\u043c\u043f\u0442\u043e\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e\u00bb \u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c\u0430 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u043c\u0435\u0442\u043e\u0434\u0430.\n\n## 5. \u041a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\n\n1. \u0424\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 p \u0438 \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u0430\u044f \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 \u043c\u043e\u0434\u0435\u043b\u0438 \u0432\u043e \u0432\u0441\u0435\u0445 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u0445.\n2. \u0424\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0435 \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u0437\u0430 \u0438\u0442\u0435\u0440\u0430\u0446\u0438\u044e \u043f\u0440\u0438 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0438 m (\u0441\u043c. \u00a73).\n3. \u041e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 \u0438 \u0441\u0438\u0434\u044b: \u043e\u0434\u0438\u043d \u0438 \u0442\u043e\u0442 \u0436\u0435 \u0448\u0430\u0440\u0434/\u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0434\u0430\u043d\u043d\u044b\u0445; \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 seed \u0434\u043b\u044f \u0438\u043d\u0438\u0446\u0438\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u0432\u0435\u0441\u043e\u0432 \u0438 \u0434\u043b\u044f \u043f\u043e\u0440\u044f\u0434\u043a\u0430 \u0434\u0430\u043d\u043d\u044b\u0445; \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u044b\u0435 \u043f\u0440\u043e\u0433\u043e\u043d\u044b R=3\u20135 \u043d\u0430 \u044f\u0447\u0435\u0439\u043a\u0443 (\u043c\u0435\u0442\u043e\u0434, m) \u0441 \u0440\u0430\u0437\u043d\u044b\u043c\u0438 \u0441\u0438\u0434\u0430\u043c\u0438 \u0434\u0430\u043d\u043d\u044b\u0445.\n4. Warmup/\u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u043e\u0441\u0442\u044c: \u043e\u0442\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0435\u043c \u043f\u0435\u0440\u0432\u044b\u0435 5 \u0438\u0442\u0435\u0440\u0430\u0446\u0438\u0439; CV<5% \u043f\u043e\u0441\u043b\u0435 warmup (\u0438\u043d\u0430\u0447\u0435 \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0432\u0430\u0435\u043c K, \u0441\u043c. \u00a72).\n5. \u041d\u0435\u0440\u0435\u043b\u0435\u0432\u0430\u043d\u0442\u043d\u044b\u0435 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0438 \u0448\u0443\u043c\u0430 \u0438\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u044b: \u0431\u0435\u0437 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u044f \u0432\u0435\u0441\u043e\u0432 (\u0438\u043b\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0442\u043e\u0440), \u0431\u0435\u0437 \u043b\u043e\u0433\u0433\u0438\u043d\u0433\u0430 \u0432 \u0433\u043e\u0440\u044f\u0447\u0435\u043c \u0446\u0438\u043a\u043b\u0435, \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0448\u0430\u0433\u043e\u0432 \u0440\u0430\u0441\u043f\u0438\u0441\u0430\u043d\u0438\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u043c\u0435\u0442\u043e\u0434\u0430.\n6. \u0421\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u043e \u0434\u043b\u044f ZB-2p: \u043f\u0440\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u044b\u0445 \u0442\u043e\u043a\u0435\u043d\u0430\u0445 \u0435\u0433\u043e \u0434\u0432\u0430 \u043f\u0440\u043e\u0445\u043e\u0434\u0430 \u043e\u0431\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0442 \u0442\u043e\u0442 \u0436\u0435 \u043e\u0431\u044a\u0451\u043c \u0442\u043e\u043a\u0435\u043d\u043e\u0432, \u0447\u0442\u043e \u0438 \u043e\u0434\u0438\u043d \u043f\u0440\u043e\u0445\u043e\u0434 \u0443 \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0445 \u043c\u0435\u0442\u043e\u0434\u043e\u0432 \u2014 \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u043e\u0435 \u043a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u0440\u0430\u0431\u043e\u0442\u044b \u0437\u0430 \u0438\u0442\u0435\u0440\u0430\u0446\u0438\u044e.\n\n**A priori \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0438 \u0440\u0435\u0448\u0435\u043d\u0438\u044f:**\n- CV \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u0438\u0442\u0435\u0440\u0430\u0446\u0438\u0438 \u043f\u043e\u0441\u043b\u0435 warmup < 5%;\n- \u043f\u043e\u0432\u0442\u043e\u0440\u044b R = 3\u20135 \u0441 \u0440\u0430\u0437\u043d\u044b\u043c\u0438 \u0441\u0438\u0434\u0430\u043c\u0438;\n- \u00ab\u0432\u044b\u0441\u043e\u043a\u0430\u044f throughput\u00bb: \u226595% \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0433\u043e \u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c\u0430 \u043f\u0440\u0438 \u043c\u0430\u043b\u043e\u043c m (ZB-2p), \u043e\u0434\u043d\u043e-\u043f\u0440\u043e\u0445\u043e\u0434\u043d\u044b\u0435 \u226485% \u0442\u0430\u043c \u0436\u0435;\n- \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0437\u043d\u0430\u0447\u0438\u043c\u043e\u0435 \u0440\u0430\u0437\u043b\u0438\u0447\u0438\u0435 = \u043d\u0435\u043f\u0435\u0440\u0435\u0441\u0435\u043a\u0430\u044e\u0449\u0438\u0435\u0441\u044f 95% CI \u0438\u043b\u0438 \u044d\u0444\u0444\u0435\u043a\u0442 >3%;\n- \u043d\u0430\u0441\u044b\u0449\u0435\u043d\u0438\u0435 \u043a\u0440\u0438\u0432\u043e\u0439: \u043f\u0440\u0438\u0440\u043e\u0441\u0442 <3% \u043f\u0440\u0438 \u0443\u0434\u0432\u043e\u0435\u043d\u0438\u0438 m \u043d\u0430 \u043f\u043b\u0430\u0442\u043e.\n\n## 6. \u041f\u043b\u0430\u043d \u0430\u043d\u0430\u043b\u0438\u0437\u0430\n\n1. **\u041a\u0440\u0438\u0432\u044b\u0435:** mean throughput (tokens/s) \u00b1 95% CI (bootstrap \u043f\u043e R \u043f\u043e\u0432\u0442\u043e\u0440\u0430\u043c) vs m, \u043e\u0441\u044c x \u043b\u043e\u0433-\u0448\u043a\u0430\u043b\u0430; \u043f\u043e \u043e\u0434\u043d\u043e\u0439 \u043a\u0440\u0438\u0432\u043e\u0439 \u043d\u0430 \u043c\u0435\u0442\u043e\u0434.\n2. **\u041d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u043a \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u043c\u0443 \u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c\u0443:** `T_method(m)/T_method(m_max)` \u2014 \u043f\u0440\u044f\u043c\u043e\u0439 \u043e\u0442\u0432\u0435\u0442 \u043d\u0430 \u0432\u043e\u043f\u0440\u043e\u0441 \u00ab\u0443\u043b\u0443\u0447\u0448\u0430\u0435\u0442\u0441\u044f \u043b\u0438 \u0441 \u0440\u043e\u0441\u0442\u043e\u043c m\u00bb \u0438 \u043d\u0430 \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u0435 \u00abZB-2p \u043f\u043b\u043e\u0441\u043a\u0438\u0439/\u0432\u044b\u0441\u043e\u043a\u0438\u0439 \u043f\u0440\u0438 \u043c\u0430\u043b\u044b\u0445 m\u00bb.\n3. **\u0414\u0438\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u043a\u0430 \u043d\u0430\u043a\u043b\u0430\u0434\u043d\u044b\u0445 \u0440\u0430\u0441\u0445\u043e\u0434\u043e\u0432:** \u0433\u0440\u0430\u0444\u0438\u043a \u00ab\u0432\u0440\u0435\u043c\u044f \u043d\u0430 \u0442\u043e\u043a\u0435\u043d vs m\u00bb \u2014 \u0435\u0441\u043b\u0438 \u043a\u0440\u0438\u0432\u044b\u0435 \u0441\u0445\u043e\u0434\u044f\u0442\u0441\u044f \u043a \u043f\u043b\u0430\u0442\u043e \u043f\u043e \u043f\u0440\u0438\u0447\u0438\u043d\u0435 \u043d\u0430\u043a\u043b\u0430\u0434\u043d\u044b\u0445 \u0440\u0430\u0441\u0445\u043e\u0434\u043e\u0432 \u043d\u0430 \u043c\u0435\u043b\u043a\u0438\u0435 \u043c\u0438\u043a\u0440\u043e\u0431\u0430\u0442\u0447\u0438 (\u0430 \u043d\u0435 \u0438\u0437-\u0437\u0430 \u043f\u0443\u0437\u044b\u0440\u044c\u043a\u043e\u0432), \u044d\u0442\u043e \u0431\u0443\u0434\u0435\u0442 \u0432\u0438\u0434\u043d\u043e; \u043f\u0440\u0438 \u043e\u0431\u043d\u0430\u0440\u0443\u0436\u0435\u043d\u0438\u0438 \u2014 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e \u043e\u0431\u0441\u0443\u0434\u0438\u0442\u044c \u0438 \u043d\u0435 \u0441\u043c\u0435\u0448\u0438\u0432\u0430\u0442\u044c \u0441 \u044d\u0444\u0444\u0435\u043a\u0442\u043e\u043c \u043f\u0443\u0437\u044b\u0440\u044c\u043a\u043e\u0432.\n4. **\u0420\u0435\u0444\u0435\u0440\u0435\u043d\u0441 \u043f\u043e \u043c\u043e\u0434\u0435\u043b\u0438 \u043f\u0443\u0437\u044b\u0440\u044c\u043a\u043e\u0432 (\u0442\u0435\u043e\u0440\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439, \u043d\u0435 \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u0438\u0435):** \u043d\u0430 \u0442\u0435 \u0436\u0435 \u043e\u0441\u0438 \u043d\u0430\u043b\u043e\u0436\u0438\u0442\u044c \u0430\u043d\u0430\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043a\u0440\u0438\u0432\u044b\u0435 bubble-ratio \u2192 \u0438\u0434\u0435\u0430\u043b\u044c\u043d\u044b\u0439 normalized throughput \u0438\u0437 \u0441\u0442\u0430\u0442\u044c\u0438 ZB \u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u043c\u0435\u0442\u043e\u0434\u0430; \u043b\u0438\u043d\u0438\u0438 \u044f\u0432\u043d\u043e \u043f\u043e\u043c\u0435\u0447\u0435\u043d\u044b \u043a\u0430\u043a \u00ab\u043e\u0436\u0438\u0434\u0430\u043d\u0438\u0435 \u043f\u043e \u0430\u043d\u0430\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043c\u043e\u0434\u0435\u043b\u0438\u00bb, \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u2014 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0435 (\u0444\u043e\u0440\u043c\u0430 \u043a\u0440\u0438\u0432\u044b\u0445, \u0442\u043e\u0447\u043a\u0430 \u043f\u043b\u0430\u0442\u043e).\n5. **\u0418\u0442\u043e\u0433\u043e\u0432\u044b\u0439 \u0432\u0435\u0440\u0434\u0438\u043a\u0442** \u043f\u043e H1/H2: \u0444\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u043e \u043f\u043e \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u044f\u043c \u00a75 \u0441 \u043e\u0442\u0447\u0451\u0442\u043e\u043c mean\u00b1CI \u043f\u043e \u043a\u0430\u0436\u0434\u043e\u0439 \u044f\u0447\u0435\u0439\u043a\u0435.\n\n## 7. \u041e\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0438\u043c\u043e\u0441\u0442\u044c \u0432 \u0434\u0430\u043d\u043d\u043e\u043c \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0438\n\n- \u0420\u0435\u0430\u043b\u044c\u043d\u044b\u0439 \u0437\u0430\u043f\u0443\u0441\u043a \u043d\u0430 GPU **\u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u0435\u043d** (\u043d\u0435\u0442 GPU \u0438 ML-\u0441\u0442\u0435\u043a\u0430) \u0438 **\u043d\u0435 \u0432\u0445\u043e\u0434\u0438\u0442 \u0432 \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442**.\n- \u0420\u0435\u0430\u043b\u044c\u043d\u043e \u0440\u0435\u0430\u043b\u0438\u0437\u0443\u0435\u043c \u0441\u0435\u0439\u0447\u0430\u0441: \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u0438\u0437\u0430\u0439\u043d-\u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442 (\u0434\u0430\u043d\u043d\u044b\u0439 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442).\n- **\u041e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0435 \u0430\u043d\u0430\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0435 (\u043d\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044f \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u043e\u043c, \u043d\u0435 \u0432\u044b\u0434\u0430\u0451\u0442\u0441\u044f \u0437\u0430 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u043d\u044b\u0439 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442):** \u0447\u0438\u0441\u0442\u044b\u0439-Python \u0441\u0438\u043c\u0443\u043b\u044f\u0442\u043e\u0440 \u0440\u0430\u0441\u043f\u0438\u0441\u0430\u043d\u0438\u0439 1F1B/1F1B-I/ZB-1p/ZB-2p \u043a\u0430\u043a \u0434\u0438\u0441\u043a\u0440\u0435\u0442\u043d\u043e-\u0441\u043e\u0431\u044b\u0442\u0438\u0439\u043d\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c (\u0442\u043e\u043b\u044c\u043a\u043e `math`/\u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u0430\u044f \u0431\u0438\u0431\u043b\u0438\u043e\u0442\u0435\u043a\u0430, numpy \u043d\u0435 \u043d\u0443\u0436\u0435\u043d), \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043f\u043e \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u043c \u043f\u0430\u0442\u0442\u0435\u0440\u043d\u0430\u043c \u0448\u0430\u0433\u043e\u0432 \u0438\u0437 \u0441\u0442\u0430\u0442\u044c\u0438 \u0432\u044b\u0447\u0438\u0441\u043b\u044f\u0435\u0442 \u0441\u0443\u043c\u043c\u044b \u0437\u0430\u043d\u044f\u0442\u044b\u0445/\u043f\u0443\u0441\u0442\u044b\u0445 \u0441\u043b\u043e\u0442\u043e\u0432 \u0437\u0430 \u0431\u0430\u0442\u0447 \u0438 \u0434\u0430\u0451\u0442 \u0442\u043e\u0447\u043d\u044b\u0435 \u0442\u0435\u043e\u0440\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043a\u0440\u0438\u0432\u044b\u0435 throughput vs m. \u042d\u0442\u043e **\u0442\u0435\u043e\u0440\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439/\u0430\u043d\u0430\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441 \u043f\u043e \u043c\u043e\u0434\u0435\u043b\u0438 \u043f\u0443\u0437\u044b\u0440\u044c\u043a\u043e\u0432**, \u0430 \u043d\u0435 \u0437\u0430\u043c\u0435\u0440 \u043d\u0430 \u0436\u0435\u043b\u0435\u0437\u0435; \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043a\u0430\u043a \u0432\u0441\u043f\u043e\u043c\u043e\u0433\u0430\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u044f \u0430\u043d\u0430\u043b\u0438\u0442\u0438\u043a\u0438 \u0438 \u043f\u0440\u0438 \u044f\u0432\u043d\u043e\u0439 \u043c\u0430\u0440\u043a\u0438\u0440\u043e\u0432\u043a\u0435.\n\n## 8. \u0414\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f (\u043f\u0440\u0435\u0434\u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u044f, \u043d\u0435 \u0444\u0430\u043a\u0442\u044b) \u0438 \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u0438\n\n**\u0414\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f:**\n- \u0420\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u043c\u0435\u0442\u043e\u0434\u043e\u0432 (\u0435\u0441\u043b\u0438 \u043a\u043e\u0434 \u043f\u043e\u044f\u0432\u0438\u0442\u0441\u044f) \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044e\u0442 \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u043c \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f\u043c \u0441\u0442\u0430\u0442\u044c\u0438 ZB (\u0440\u0430\u0441\u043f\u0438\u0441\u0430\u043d\u0438\u044f \u0448\u0430\u0433\u043e\u0432, \u00ab1p\u00bb \u2014 \u043e\u0434\u0438\u043d \u043f\u0440\u043e\u0445\u043e\u0434 \u043d\u0430\u0437\u0430\u0434, \u00ab2p\u00bb \u2014 \u0434\u0432\u0430 \u043f\u0440\u043e\u0445\u043e\u0434\u0430).\n- \u0422\u043e\u0447\u043d\u044b\u0435 \u043a\u043e\u043d\u0441\u0442\u0430\u043d\u0442\u044b bubble-ratio \u0444\u043e\u0440\u043c\u0443\u043b \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u043c\u044b \u043d\u0430 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u0443\u044e \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044e \u0438 \u0431\u0443\u0434\u0443\u0442 \u0441\u0432\u0435\u0440\u044f\u0442\u044c\u0441\u044f \u0441 \u043a\u043e\u0434\u043e\u043c \u043f\u0440\u0438 \u0435\u0433\u043e \u043f\u043e\u044f\u0432\u043b\u0435\u043d\u0438\u0438.\n- \u0412\u044b\u0431\u043e\u0440 \u043c\u0430\u0441\u0448\u0442\u0430\u0431\u0430 \u043c\u043e\u0434\u0435\u043b\u0438 \u0438 p=8 (\u0438\u043b\u0438 4) \u2014 \u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u043f\u0440\u043e\u0435\u043a\u0442\u0430 \u0434\u043b\u044f \u0432\u043f\u0438\u0441\u044b\u0432\u0430\u043d\u0438\u044f \u0432 \u0431\u044e\u0434\u0436\u0435\u0442, \u043d\u0435 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0435 \u0437\u0430\u0434\u0430\u0447\u0438.\n- \u041a\u0440\u0438\u0442\u0435\u0440\u0438\u0438 \u00ab\u0432\u044b\u0441\u043e\u043a\u043e\u0439 throughput\u00bb (95%/85%, \u044d\u0444\u0444\u0435\u043a\u0442 >3%, CV<5%, R=3\u20135) \u2014 \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u043d\u044b\u0435 a priori \u043f\u0440\u043e\u0435\u043a\u0442\u043e\u043c.\n- \u041f\u0440\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u044b\u0445 \u0442\u043e\u043a\u0435\u043d\u0430\u0445 \u0443\u043c\u0435\u043d\u044c\u0448\u0435\u043d\u0438\u0435 \u043c\u0438\u043a\u0440\u043e\u0431\u0430\u0442\u0447\u0430 \u0441\u0430\u043c\u043e \u043f\u043e \u0441\u0435\u0431\u0435 \u043d\u0435 \u0432\u043d\u043e\u0441\u0438\u0442 \u0437\u043d\u0430\u0447\u0438\u043c\u044b\u0445 \u043d\u0430\u043a\u043b\u0430\u0434\u043d\u044b\u0445 \u0440\u0430\u0441\u0445\u043e\u0434\u043e\u0432 (\u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u00a76.3).\n- \u0417\u0430\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435 \u043e\u0431 \u00ab\u0443\u043b\u0443\u0447\u0448\u0435\u043d\u0438\u0438 \u0441 \u0440\u043e\u0441\u0442\u043e\u043c m\u00bb \u0444\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0433\u043e \u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c\u0430 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u043c\u0435\u0442\u043e\u0434\u0430.\n- \u0420\u0435\u0441\u0443\u0440\u0441\u044b/\u0431\u044e\u0434\u0436\u0435\u0442 \u043f\u0440\u0438 \u0431\u0443\u0434\u0443\u0449\u0435\u043c \u0437\u0430\u043f\u0443\u0441\u043a\u0435 (\u043c\u0438\u043d\u0443\u0442\u044b \u043d\u0430 \u044f\u0447\u0435\u0439\u043a\u0443, \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u043e \u0441\u043e\u0442\u043d\u0438 \u043c\u0438\u043d\u0443\u0442) \u2014 \u043f\u0440\u0435\u0434\u043f\u043e\u043b\u043e\u0436\u0438\u0442\u0435\u043b\u044c\u043d\u044b, \u0442\u0430\u043a \u043a\u0430\u043a \u043a\u043b\u0430\u0441\u0442\u0435\u0440 \u043d\u0435 \u0437\u0430\u0434\u0430\u043d.\n\n**\u041d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u0438:**\n- \u041a\u043e\u0434 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0439 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442 \u2014 \u0438\u043c\u0435\u043d\u0430 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432 (\u0447\u0438\u0441\u043b\u043e \u043c\u0438\u043a\u0440\u043e\u0431\u0430\u0442\u0447\u0435\u0439, \u0440\u0430\u0437\u043c\u0435\u0440 \u043c\u0438\u0440\u0430, \u0433\u043b\u0443\u0431\u0438\u043d\u0430) \u0438 \u043a\u043e\u043d\u0444\u0438\u0433\u0438 \u0438\u0437 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044c \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e.\n- \u0422\u043e\u0447\u043d\u043e\u0441\u0442\u044c \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0430 \u0430\u043d\u0430\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0444\u043e\u0440\u043c\u0443\u043b \u0441\u0442\u0430\u0442\u044c\u0438 \u043d\u0430 (\u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0443\u044e) \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044e \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u0430.\n- \u0427\u0438\u0441\u043b\u043e GPU \u0438 \u0431\u044e\u0434\u0436\u0435\u0442 \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u0431\u0443\u0434\u0443\u0449\u0435\u0433\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430 \u043d\u0435 \u0437\u0430\u0434\u0430\u043d\u044b.", "evidence": "- `ls -la /workspace` \u0438 `find /workspace -type f` \u2192 \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0444\u0430\u0439\u043b `task.json`; \u0437\u0430\u043c\u0435\u0442\u043a\u0430 `track.md`: \u00abDesign-only task; repositories and compute are not required.\u00bb.\n- \u041f\u043e\u043b\u043d\u044b\u0439 \u043f\u043e\u0438\u0441\u043a \u043f\u043e \u0424\u0421 (\u043a\u0430\u0442\u0430\u043b\u043e\u0433\u0438 pipeline/Megatron/DeepSeek/zb \u0438 `grep -ril 'zero.bubble|ZB-1p|zbv|bubble' /`) \u2192 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0439/\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0432/\u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u0438 \u043d\u0435\u0442.\n- `python3 -c \"import importlib.util as u; ...\"` \u0434\u043b\u044f torch/paddle/tensorflow/deepspeed/numpy/matplotlib/pandas \u2192 \u0432\u0441\u0435 \u043d\u0435 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u044b; GPU \u043d\u0435\u0442 (`gpu_enabled: false`).\n- \u041f\u043e\u0434\u0445\u043e\u0434 \u043e\u0434\u043e\u0431\u0440\u0435\u043d \u0440\u0435\u0446\u0435\u043d\u0437\u0435\u043d\u0442\u043e\u043c (approach_approved=true) \u0441 \u0443\u043a\u0430\u0437\u0430\u043d\u0438\u0435\u043c \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f \u043a\u0430\u043a \u043f\u0440\u0435\u0434\u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u044f, \u0441\u0438\u043c\u0443\u043b\u044f\u0442\u043e\u0440 \u0434\u0435\u0440\u0436\u0430\u0442\u044c \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e \u0438 \u043f\u043e\u043c\u0435\u0447\u0430\u0442\u044c \u043a\u0430\u043a \u0442\u0435\u043e\u0440\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441, \u043d\u0435 \u0437\u0430\u044f\u0432\u043b\u044f\u0442\u044c \u043e \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u043d\u043e\u043c \u043f\u0440\u043e\u0433\u043e\u043d\u0435.", "assumptions": ["\u041a\u043e\u0434 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0439 \u0432 \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0438 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442 (\u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u043e \u043e\u0441\u043c\u043e\u0442\u0440\u043e\u043c) \u2014 \u0432\u0441\u0435 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u0432\u044b\u0435 \u0434\u0435\u0442\u0430\u043b\u0438 \u043e \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0438 \u043d\u0435 \u0432\u044b\u0434\u0443\u043c\u044b\u0432\u0430\u044e\u0442\u0441\u044f.", "\u0420\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 1F1B/1F1B-I/ZB-1p/ZB-2p (\u043f\u0440\u0438 \u043f\u043e\u044f\u0432\u043b\u0435\u043d\u0438\u0438) \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044e\u0442 \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u043c \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f\u043c \u0441\u0442\u0430\u0442\u044c\u0438 ZB.", "\u0410\u043d\u0430\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 bubble-ratio \u0444\u043e\u0440\u043c\u0443\u043b\u044b \u0441\u0442\u0430\u0442\u044c\u0438 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u043c\u044b \u043d\u0430 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u0443\u044e \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044e (\u043f\u043e\u0442\u0440\u0435\u0431\u0443\u044e\u0442 \u0441\u0432\u0435\u0440\u043a\u0438 \u0441 \u043a\u043e\u0434\u043e\u043c).", "\u0412\u044b\u0431\u043e\u0440 \u043c\u0430\u0441\u0448\u0442\u0430\u0431\u0430 \u043c\u043e\u0434\u0435\u043b\u0438 (~350M\u20131.3B) \u0438 p=8 (\u0437\u0430\u043f\u0430\u0441\u043d\u043e\u0439 p=4) \u2014 \u0432\u044b\u0431\u043e\u0440 \u043f\u0440\u043e\u0435\u043a\u0442\u0438\u0440\u043e\u0432\u0449\u0438\u043a\u0430, \u043d\u0435 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0435 \u0437\u0430\u0434\u0430\u0447\u0438.", "A priori \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0438 (CV<5%, R=3\u20135 \u043f\u043e\u0432\u0442\u043e\u0440\u043e\u0432, 95%/85% \u043e\u0442 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0433\u043e \u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c\u0430, \u044d\u0444\u0444\u0435\u043a\u0442 >3%) \u2014 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0438 \u043f\u0440\u043e\u0435\u043a\u0442\u0430.", "\u0423\u043c\u0435\u043d\u044c\u0448\u0435\u043d\u0438\u0435 \u043c\u0438\u043a\u0440\u043e\u0431\u0430\u0442\u0447\u0430 \u043f\u0440\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u044b\u0445 \u0442\u043e\u043a\u0435\u043d\u0430\u0445 \u043d\u0435 \u0432\u043d\u043e\u0441\u0438\u0442 \u0441\u0430\u043c\u043e \u043f\u043e \u0441\u0435\u0431\u0435 \u0437\u043d\u0430\u0447\u0438\u043c\u044b\u0445 \u043d\u0430\u043a\u043b\u0430\u0434\u043d\u044b\u0445 \u0440\u0430\u0441\u0445\u043e\u0434\u043e\u0432 (\u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u0434\u0438\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u043a\u043e\u0439 \u00ab\u0432\u0440\u0435\u043c\u044f \u043d\u0430 \u0442\u043e\u043a\u0435\u043d vs m\u00bb).", "\u00ab\u0423\u043b\u0443\u0447\u0448\u0435\u043d\u0438\u0435 \u0441 \u0440\u043e\u0441\u0442\u043e\u043c m\u00bb \u0438 \u00ab\u0432\u044b\u0441\u043e\u043a\u0430\u044f throughput ZB-2p\u00bb \u0444\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0433\u043e \u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c\u0430 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u043c\u0435\u0442\u043e\u0434\u0430.", "\u041e\u0446\u0435\u043d\u043a\u0438 \u0431\u044e\u0434\u0436\u0435\u0442\u0430 \u0431\u0443\u0434\u0443\u0449\u0435\u0433\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430 (\u043c\u0438\u043d\u0443\u0442\u044b \u043d\u0430 \u044f\u0447\u0435\u0439\u043a\u0443, \u0441\u043e\u0442\u043d\u0438 \u043c\u0438\u043d\u0443\u0442 \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u043e) \u043f\u0440\u0435\u0434\u043f\u043e\u043b\u043e\u0436\u0438\u0442\u0435\u043b\u044c\u